import{_ as e,c as t,o,a as r}from"./app.9a45957d.js";const m=JSON.parse('{"title":"Get started — install & set up ReplyBridge","description":"Step-by-step guide to install ReplyBridge, connect your Instagram, and turn on your first automatic reply. No technical background needed.","frontmatter":{"title":"Get started — install & set up ReplyBridge","description":"Step-by-step guide to install ReplyBridge, connect your Instagram, and turn on your first automatic reply. No technical background needed."},"headers":[{"level":2,"title":"Before you begin (2-minute check)","slug":"before-you-begin-2-minute-check","link":"#before-you-begin-2-minute-check","children":[]},{"level":2,"title":"Step 1 — Install the app","slug":"step-1-—-install-the-app","link":"#step-1-—-install-the-app","children":[]},{"level":2,"title":"Step 2 — Sign in to ReplyBridge","slug":"step-2-—-sign-in-to-replybridge","link":"#step-2-—-sign-in-to-replybridge","children":[]},{"level":2,"title":"Step 3 — Connect your Instagram","slug":"step-3-—-connect-your-instagram","link":"#step-3-—-connect-your-instagram","children":[]},{"level":2,"title":"Step 4 — Choose a post and turn on automation","slug":"step-4-—-choose-a-post-and-turn-on-automation","link":"#step-4-—-choose-a-post-and-turn-on-automation","children":[]},{"level":2,"title":"Step 5 — Write your messages (the important part)","slug":"step-5-—-write-your-messages-the-important-part","link":"#step-5-—-write-your-messages-the-important-part","children":[]},{"level":2,"title":"Step 6 — Check that it works","slug":"step-6-—-check-that-it-works","link":"#step-6-—-check-that-it-works","children":[]},{"level":2,"title":"Need more help?","slug":"need-more-help","link":"#need-more-help","children":[]},{"level":2,"title":"For marketers & creators","slug":"for-marketers-creators","link":"#for-marketers-creators","children":[]}],"relativePath":"replybridge/getting-started.md"}'),n={name:"replybridge/getting-started.md"},a=r('<h1 id="get-started-with-replybridge" tabindex="-1">Get started with ReplyBridge <a class="header-anchor" href="#get-started-with-replybridge" aria-hidden="true">#</a></h1><p>If you found us on <strong>Instagram</strong> and left a comment, thank you. This page is the <strong>full guide</strong> we send by DM—so you can install the app and finish setup <strong>without guessing any steps</strong>.</p><p><strong>What ReplyBridge does (in plain words):</strong> When someone comments on your post, it can send them a <strong>private message (DM)</strong> you wrote ahead of time, and/or leave a <strong>public reply</strong> under their comment—so you don’t have to copy‑paste the same answer all day.</p><p><strong>Who this is for:</strong> Shop owners, creators, and anyone running an <strong>Instagram Business or Creator</strong> account who wants to save time on comments and DMs.</p><hr><h2 id="before-you-begin-2-minute-check" tabindex="-1">Before you begin (2-minute check) <a class="header-anchor" href="#before-you-begin-2-minute-check" aria-hidden="true">#</a></h2><p>ReplyBridge works with Instagram’s official tools. Please check:</p><ol><li><strong>Account type</strong> — Your Instagram should be a <strong>Business</strong> or <strong>Creator</strong> account (not a personal profile only).</li><li><strong>Facebook Page</strong> — Instagram often needs to be <strong>connected to a Facebook Page</strong>. If you’re not sure, open the Instagram app → <strong>Settings</strong> → <strong>Account</strong> and follow Meta’s prompts, or use the hints inside ReplyBridge when you connect.</li></ol><p>If something here is missing, the app will usually tell you what to fix.</p><hr><h2 id="step-1-—-install-the-app" tabindex="-1">Step 1 — Install the app <a class="header-anchor" href="#step-1-—-install-the-app" aria-hidden="true">#</a></h2><p><strong>Fastest way:</strong> open this link on your iPhone and tap <strong>Get</strong> or <strong>Download</strong>:</p><p>👉 <strong><a href="https://apps.apple.com/us/app/replybridge/id6761187664" target="_blank" rel="noreferrer">ReplyBridge on the App Store</a></strong></p><p>Or:</p><ol><li>Open the <strong>App Store</strong> on your iPhone.</li><li>Search for <strong>ReplyBridge</strong> and install the app by <strong>TLDR</strong> (same as our Instagram bio).</li><li>Open ReplyBridge once so it can finish any updates.</li></ol><div class="tip custom-block"><p class="custom-block-title">No iPhone?</p><p>ReplyBridge is built for <strong>iOS</strong> today. If you use Android, watch our Instagram for updates—or send us a message via <a href="/contact">Contact</a>.</p></div><hr><h2 id="step-2-—-sign-in-to-replybridge" tabindex="-1">Step 2 — Sign in to ReplyBridge <a class="header-anchor" href="#step-2-—-sign-in-to-replybridge" aria-hidden="true">#</a></h2><ol><li>Open <strong>ReplyBridge</strong>.</li><li>Sign in with the method shown on screen (for example <strong>email</strong> or <strong>Sign in with Apple</strong>—whatever the app offers).</li><li>Stay logged in so Instagram stays connected later.</li></ol><p>You <strong>do not</strong> need to create a “developer” account or touch any coding settings.</p><hr><h2 id="step-3-—-connect-your-instagram" tabindex="-1">Step 3 — Connect your Instagram <a class="header-anchor" href="#step-3-—-connect-your-instagram" aria-hidden="true">#</a></h2><ol><li>In the app, find <strong>Connect Instagram</strong>, <strong>Link account</strong>, or similar.</li><li>The app will open a <strong>browser</strong> (often Safari) to log in to <strong>Facebook / Instagram</strong> and approve permissions. This is normal and required by Instagram.</li><li>Approve the permissions the app asks for—ReplyBridge only uses what it needs to read comments and send messages you configure.</li><li>When you return to ReplyBridge, you should see that your account is <strong>connected</strong> or <strong>active</strong>.</li></ol><p><strong>If it fails:</strong> Check Wi‑Fi, update Instagram and Facebook apps, then tap <strong>Connect</strong> or <strong>Try again</strong> inside ReplyBridge. See also <a href="/replybridge/integration">Connect Instagram</a> for a bit more detail.</p><hr><h2 id="step-4-—-choose-a-post-and-turn-on-automation" tabindex="-1">Step 4 — Choose a post and turn on automation <a class="header-anchor" href="#step-4-—-choose-a-post-and-turn-on-automation" aria-hidden="true">#</a></h2><ol><li>In ReplyBridge, open your <strong>recent posts</strong> (or <strong>media</strong> list).</li><li><strong>Pick one post</strong> you want to automate first—for example a post that gets lots of “How much?” or “Link please?” comments.</li><li>Turn <strong>on</strong> automation for that post (the exact switch name may say <strong>Auto DM</strong>, <strong>Automation</strong>, or similar).</li></ol><p>You can start with <strong>one post</strong> only. You can add more later.</p><hr><h2 id="step-5-—-write-your-messages-the-important-part" tabindex="-1">Step 5 — Write your messages (the important part) <a class="header-anchor" href="#step-5-—-write-your-messages-the-important-part" aria-hidden="true">#</a></h2><p>For that post, set:</p><table><thead><tr><th>What you set</th><th>Simple explanation</th></tr></thead><tbody><tr><td><strong>DM message</strong></td><td>The private message people receive in their inbox after they comment. Put your price list, link, coupon code, or “reply YES” instruction here.</td></tr><tr><td><strong>Keywords (optional)</strong></td><td>Only react when the comment contains certain words (e.g. “price”, “link”). Helps avoid spam.</td></tr><tr><td><strong>Public reply (optional)</strong></td><td>A short answer everyone can see under the comment—great for FAQs.</td></tr><tr><td><strong>Once per person</strong></td><td>Sends the DM only <strong>once</strong> to the same person on that post—useful for giveaways or lead capture.</td></tr><tr><td><strong>How long it runs</strong></td><td>Your automation turns off after a date you choose—good for limited sales or events.</td></tr></tbody></table><p>Save your settings. From then on, new comments on that post can trigger your DM and reply <strong>automatically</strong>, according to your rules.</p><hr><h2 id="step-6-—-check-that-it-works" tabindex="-1">Step 6 — Check that it works <a class="header-anchor" href="#step-6-—-check-that-it-works" aria-hidden="true">#</a></h2><ol><li>From another account (or ask a friend), <strong>leave a test comment</strong> on the post you enabled.</li><li>Wait a short moment. The account should receive your <strong>DM</strong> and/or see your <strong>public reply</strong>, depending on what you turned on.</li></ol><p>If nothing arrives, double‑check: correct post selected, keywords match the test comment, automation window not expired, and Instagram still connected.</p><hr><h2 id="need-more-help" tabindex="-1">Need more help? <a class="header-anchor" href="#need-more-help" aria-hidden="true">#</a></h2><ul><li><strong>Short how‑to:</strong> <a href="/replybridge/usage">How to use ReplyBridge</a> (same ideas, a bit more detail).</li><li><strong>Connection issues:</strong> <a href="/replybridge/integration">Connect Instagram</a>.</li><li><strong>Questions for our team:</strong> <a href="/contact">Contact</a> — include your Instagram handle and what step you’re stuck on.</li></ul><hr><h2 id="for-marketers-creators" tabindex="-1">For marketers &amp; creators <a class="header-anchor" href="#for-marketers-creators" aria-hidden="true">#</a></h2><p>Ideas for posts, Reels, and carousels live under <a href="/replybridge/marketing/">Marketing &amp; tips</a>—still written for <strong>people who run Instagram</strong>, not for engineers.</p><p>Welcome aboard—we’re glad you’re here from Instagram.</p>',44),s=[a];function i(l,p,g,d,h,c){return o(),t("div",null,s)}const y=e(n,[["render",i]]);export{m as __pageData,y as default};
